function split(s, sep)
    local out = {}
    local start = 1
    while true do
        local at = s:find(sep, start, true)
        if not at then
            out[#out + 1] = s:sub(start)
            return out
        end
        out[#out + 1] = s:sub(start, at - 1)
        start = at + #sep
    end
end

function words(s)
    local out = {}
    for w in s:gmatch("[%a']+") do out[#out + 1] = w:lower() end
    return out
end

function fill(template, values)
    return (template:gsub("{([%w_]+)}", function(name)
        if values[name] ~= nil then return tostring(values[name]) end
    end))
end

function title_case(s)
    return (s:gsub("(%a)(%a*)", function(first, rest)
        return first:upper() .. rest:lower()
    end))
end
